CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Jogador' CHECK (char_length(display_name) BETWEEN 2 AND 50), avatar_url text, leaderboard_enabled boolean NOT NULL DEFAULT false, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id, left(coalesce(nullif(NEW.raw_user_meta_data->>'display_name',''),nullif(NEW.raw_user_meta_data->>'name',''),'Jogador'),50)); RETURN NEW; END $$;
CREATE TRIGGER respawn_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE TABLE public.player_library (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), favorite boolean NOT NULL DEFAULT false, played_at timestamptz, PRIMARY KEY(user_id,game_name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.player_library TO authenticated; GRANT ALL ON public.player_library TO service_role;
ALTER TABLE public.player_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_library ON public.player_library FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.game_ratings (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), PRIMARY KEY(user_id,game_name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_ratings TO authenticated; GRANT ALL ON public.game_ratings TO service_role;
ALTER TABLE public.game_ratings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_ratings ON public.game_ratings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.play_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.play_events TO authenticated; GRANT ALL ON public.play_events TO service_role;
ALTER TABLE public.play_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_plays_read ON public.play_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_plays_write ON public.play_events FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE INDEX plays_user_time ON public.play_events(user_id,created_at);
CREATE TABLE public.game_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 100), description text NOT NULL DEFAULT '' CHECK(char_length(description)<=500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_requests TO authenticated; GRANT ALL ON public.game_requests TO service_role;
ALTER TABLE public.game_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_requests ON public.game_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY own_requests_update ON public.game_requests FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY own_requests_delete ON public.game_requests FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.request_votes(request_id uuid REFERENCES public.game_requests(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(request_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.request_votes TO authenticated; GRANT ALL ON public.request_votes TO service_role;
ALTER TABLE public.request_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_vote_read ON public.request_votes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_vote_insert ON public.request_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY own_vote_delete ON public.request_votes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.game_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, game_name text NOT NULL, message text NOT NULL CHECK(char_length(message) BETWEEN 5 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.game_feedback TO authenticated; GRANT ALL ON public.game_feedback TO service_role;
ALTER TABLE public.game_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_feedback_read ON public.game_feedback FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_feedback_insert ON public.game_feedback FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY saves_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.rtc_rooms (id uuid PRIMARY KEY, host_id uuid NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 hour');
GRANT ALL ON public.rtc_rooms TO service_role;
ALTER TABLE public.rtc_rooms ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rtc_members(room_id uuid REFERENCES public.rtc_rooms(id) ON DELETE CASCADE, peer_id uuid NOT NULL, user_id uuid NOT NULL, name text NOT NULL, seen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,peer_id));
GRANT ALL ON public.rtc_members TO service_role;
ALTER TABLE public.rtc_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rtc_signals(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, room_id uuid REFERENCES public.rtc_rooms(id) ON DELETE CASCADE, sender uuid NOT NULL, recipient uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('offer','answer','ice')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rtc_signals TO service_role;
ALTER TABLE public.rtc_signals ENABLE ROW LEVEL SECURITY;
CREATE INDEX rtc_recipient ON public.rtc_signals(room_id,recipient,id);
CREATE FUNCTION public.rtc_exchange(_room uuid,_peer uuid,_op text DEFAULT 'poll',_name text DEFAULT '',_since bigint DEFAULT 0,_to uuid DEFAULT NULL,_kind text DEFAULT NULL,_payload jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; result jsonb; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF;
IF _op NOT IN ('poll','signal','leave') THEN RAISE EXCEPTION 'Invalid operation'; END IF;
DELETE FROM rtc_rooms WHERE expires_at<now();
IF _op='poll' THEN
INSERT INTO rtc_rooms(id,host_id) VALUES(_room,auth.uid()) ON CONFLICT DO NOTHING;
PERFORM 1 FROM rtc_rooms WHERE id=_room FOR UPDATE;
SELECT user_id INTO owner FROM rtc_members WHERE room_id=_room AND peer_id=_peer;
IF owner IS NOT NULL AND owner<>auth.uid() THEN RAISE EXCEPTION 'Peer ownership mismatch'; END IF;
DELETE FROM rtc_members WHERE room_id=_room AND seen_at<now()-interval '30 seconds';
IF owner IS NULL AND (SELECT count(*) FROM rtc_members WHERE room_id=_room)>=4 THEN RAISE EXCEPTION 'Room full'; END IF;
INSERT INTO rtc_members(room_id,peer_id,user_id,name) VALUES(_room,_peer,auth.uid(),left(_name,50)) ON CONFLICT(room_id,peer_id) DO UPDATE SET seen_at=now();
DELETE FROM rtc_signals WHERE room_id=_room AND created_at<now()-interval '2 minutes';
SELECT jsonb_build_object('peers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',peer_id,'name',name)) FROM rtc_members WHERE room_id=_room),'[]'::jsonb),'signals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'from',sender,'kind',kind,'payload',payload) ORDER BY id) FROM (SELECT * FROM rtc_signals WHERE room_id=_room AND recipient=_peer AND id>_since ORDER BY id LIMIT 100)s),'[]'::jsonb)) INTO result;
RETURN result;
END IF;
IF NOT EXISTS(SELECT 1 FROM rtc_members WHERE room_id=_room AND peer_id=_peer AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF;
IF _op='leave' THEN DELETE FROM rtc_members WHERE room_id=_room AND peer_id=_peer; RETURN '{}'::jsonb; END IF;
IF NOT EXISTS(SELECT 1 FROM rtc_members WHERE room_id=_room AND peer_id=_to AND seen_at>now()-interval '30 seconds') THEN RAISE EXCEPTION 'Recipient unavailable'; END IF;
IF _kind NOT IN ('offer','answer','ice') OR octet_length(_payload::text)>32768 THEN RAISE EXCEPTION 'Invalid signal'; END IF;
IF (SELECT count(*) FROM rtc_signals WHERE sender=_peer AND created_at>now()-interval '1 second')>=30 THEN RAISE EXCEPTION 'Too many signals'; END IF;
INSERT INTO rtc_signals(room_id,sender,recipient,kind,payload) VALUES(_room,_peer,_to,_kind,_payload); RETURN '{}'::jsonb;
END $$;
REVOKE ALL ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) TO service_role;
CREATE TABLE public.challenge_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, day date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, step integer NOT NULL DEFAULT 0, score integer NOT NULL DEFAULT 0, last_hit timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.challenge_runs TO authenticated; GRANT ALL ON public.challenge_runs TO service_role;
ALTER TABLE public.challenge_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_challenges ON public.challenge_runs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.start_daily_challenge() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre para competir'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT count(*) INTO n FROM challenge_runs WHERE user_id=auth.uid() AND day=(now() AT TIME ZONE 'UTC')::date; IF n>=3 THEN RAISE EXCEPTION 'Suas três tentativas de hoje acabaram'; END IF; INSERT INTO challenge_runs(user_id) VALUES(auth.uid()) RETURNING * INTO r; RETURN jsonb_build_object('id',r.id,'step',0,'score',0,'target',extract(doy FROM r.day)::integer%4,'remaining',3-n-1); END $$;
REVOKE ALL ON FUNCTION public.start_daily_challenge() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_daily_challenge() TO authenticated;
CREATE FUNCTION public.hit_daily_target(_run uuid,_direction integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; expected integer; elapsed numeric; BEGIN SELECT * INTO r FROM challenge_runs WHERE id=_run AND user_id=auth.uid() FOR UPDATE; IF r.id IS NULL OR r.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Partida encerrada'; END IF; IF r.day<>(now() AT TIME ZONE 'UTC')::date OR now()-r.started_at>interval '60 seconds' THEN UPDATE challenge_runs SET finished_at=now() WHERE id=r.id; RETURN jsonb_build_object('done',true,'score',r.score,'step',r.step); END IF; expected=(extract(doy FROM r.day)::integer+r.step*7)%4; elapsed=extract(epoch FROM now()-r.last_hit)*1000; IF elapsed<150 THEN RAISE EXCEPTION 'Aguarde o próximo alvo'; END IF; UPDATE challenge_runs SET step=step+1,score=score+CASE WHEN _direction=expected THEN greatest(10,100-floor(elapsed/50)::integer) ELSE 0 END,last_hit=now(),finished_at=CASE WHEN step+1>=20 THEN now() ELSE NULL END WHERE id=r.id RETURNING * INTO r; RETURN jsonb_build_object('done',r.finished_at IS NOT NULL,'step',r.step,'score',r.score,'target',(extract(doy FROM r.day)::integer+r.step*7)%4); END $$;
REVOKE ALL ON FUNCTION public.hit_daily_target(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hit_daily_target(uuid,integer) TO authenticated;
CREATE FUNCTION public.daily_challenge_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT p.display_name,max(r.score) AS score FROM challenge_runs r JOIN profiles p ON p.id=r.user_id WHERE r.day=(now() AT TIME ZONE 'UTC')::date AND r.finished_at IS NOT NULL AND p.leaderboard_enabled GROUP BY p.id,p.display_name ORDER BY max(r.score) DESC LIMIT 20)t $$;
REVOKE ALL ON FUNCTION public.daily_challenge_board() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_challenge_board() TO anon,authenticated;
REVOKE ALL ON FUNCTION public.create_player_profile() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.validate_player_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.avatar_url IS NOT NULL AND (octet_length(NEW.avatar_url)>150000 OR NEW.avatar_url !~ '^data:image/(webp|png|jpeg);base64,[A-Za-z0-9+/=]+$') THEN RAISE EXCEPTION 'Invalid avatar'; END IF; IF octet_length(NEW.preferences::text)>10000 THEN RAISE EXCEPTION 'Preferences too large'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_player_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_player_profile();
CREATE TABLE public.action_budgets (user_id uuid NOT NULL, action text NOT NULL, window_start timestamptz NOT NULL, hits integer NOT NULL DEFAULT 0, PRIMARY KEY(user_id,action,window_start));
GRANT ALL ON public.action_budgets TO service_role;
ALTER TABLE public.action_budgets ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_action_budget(_action text,_maximum integer,_seconds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE slot timestamptz; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF; slot=to_timestamp(floor(extract(epoch FROM now())/_seconds)*_seconds); INSERT INTO action_budgets(user_id,action,window_start,hits) VALUES(auth.uid(),_action,slot,1) ON CONFLICT(user_id,action,window_start) DO UPDATE SET hits=action_budgets.hits+1 RETURNING hits INTO n; IF n>_maximum THEN RAISE EXCEPTION 'Limite de ações atingido. Aguarde antes de tentar novamente.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.consume_action_budget(text,integer,integer) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.limit_community_writes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.created_at=now(); IF TG_TABLE_NAME='game_requests' THEN PERFORM consume_action_budget('request',10,86400); ELSE PERFORM consume_action_budget('feedback',30,86400); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.limit_community_writes() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER limit_requests BEFORE INSERT ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.limit_community_writes();
CREATE TRIGGER limit_feedback BEFORE INSERT ON public.game_feedback FOR EACH ROW EXECUTE FUNCTION public.limit_community_writes();
CREATE OR REPLACE FUNCTION public.limit_player_plays() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.created_at=now(); PERFORM consume_action_budget('open',1,10); PERFORM consume_action_budget('open_daily',100,86400); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.limit_player_plays() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER play_rate_limit BEFORE INSERT ON public.play_events FOR EACH ROW EXECUTE FUNCTION public.limit_player_plays();
CREATE OR REPLACE FUNCTION public.limit_social_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM consume_action_budget(TG_TABLE_NAME,30,60); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER rating_budget BEFORE INSERT OR UPDATE OR DELETE ON public.game_ratings FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE TRIGGER vote_budget BEFORE INSERT OR DELETE ON public.request_votes FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE OR REPLACE FUNCTION public.finish_daily_challenge(_run uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; BEGIN SELECT * INTO r FROM challenge_runs WHERE id=_run AND user_id=auth.uid() FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Partida indisponível'; END IF; IF r.finished_at IS NULL AND (now()-r.started_at>=interval '60 seconds' OR r.day<>(now() AT TIME ZONE 'UTC')::date) THEN UPDATE challenge_runs SET finished_at=now() WHERE id=r.id RETURNING * INTO r; END IF; RETURN jsonb_build_object('done',r.finished_at IS NOT NULL,'step',r.step,'score',r.score); END $$;
REVOKE ALL ON FUNCTION public.finish_daily_challenge(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finish_daily_challenge(uuid) TO authenticated;
CREATE INDEX requests_author_date ON public.game_requests(user_id,created_at DESC);
CREATE INDEX feedback_author_date ON public.game_feedback(user_id,created_at DESC);
CREATE INDEX challenge_user_day ON public.challenge_runs(user_id,day);
CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.admin_access(user_id uuid PRIMARY KEY,session_id text NOT NULL DEFAULT '',expires_at timestamptz NOT NULL DEFAULT now(),failures integer NOT NULL DEFAULT 0,blocked_until timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_access TO service_role;
ALTER TABLE public.admin_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,action text NOT NULL,resource text NOT NULL DEFAULT '',details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated;
GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.admin_is_unlocked() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM admin_access WHERE user_id=auth.uid() AND session_id=coalesce(auth.jwt()->>'session_id','') AND session_id<>'' AND expires_at>now() AND blocked_until<=now()) $$;
REVOKE ALL ON FUNCTION public.admin_is_unlocked() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_is_unlocked() TO authenticated;
CREATE POLICY admin_audit_read ON public.admin_audit FOR SELECT TO authenticated USING(public.admin_is_unlocked());
CREATE OR REPLACE FUNCTION public.assign_respawn_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='gregorigabriel16@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_respawn_owner() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER respawn_verified_owner AFTER INSERT OR UPDATE OF email,email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_respawn_owner();
CREATE OR REPLACE FUNCTION public.record_admin_attempt(_user uuid,_session text,_success boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r admin_access; BEGIN IF NOT has_role(_user,'admin') OR length(_session)=0 THEN RETURN jsonb_build_object('ok',false); END IF; INSERT INTO admin_access(user_id) VALUES(_user) ON CONFLICT DO NOTHING; SELECT * INTO r FROM admin_access WHERE user_id=_user FOR UPDATE; IF r.blocked_until>now() THEN RETURN jsonb_build_object('ok',false,'blocked',true); END IF; IF _success THEN UPDATE admin_access SET session_id=_session,expires_at=now()+interval '15 minutes',failures=0 WHERE user_id=_user; ELSE UPDATE admin_access SET failures=failures+1,expires_at=now(),blocked_until=CASE WHEN failures+1>=5 THEN now()+interval '15 minutes' ELSE now() END WHERE user_id=_user; END IF; INSERT INTO admin_audit(actor_id,action) VALUES(_user,CASE WHEN _success THEN 'admin_unlock' ELSE 'admin_code_rejected' END); RETURN jsonb_build_object('ok',_success); END $$;
REVOKE ALL ON FUNCTION public.record_admin_attempt(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_admin_attempt(uuid,text,boolean) TO service_role;
ALTER TABLE public.game_requests ADD COLUMN status text NOT NULL DEFAULT 'open';
ALTER TABLE public.game_requests ADD CONSTRAINT request_status_valid CHECK(status IN ('open','review','resolved','rejected'));
CREATE OR REPLACE FUNCTION public.preserve_request_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.created_at=OLD.created_at; IF NEW.status<>OLD.status AND NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso administrativo necessário'; END IF; RETURN NEW; END $$;
CREATE TRIGGER preserve_request_date BEFORE UPDATE ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.preserve_request_date();
CREATE POLICY admin_requests_update ON public.game_requests FOR UPDATE TO authenticated USING(public.admin_is_unlocked()) WITH CHECK(public.admin_is_unlocked());
CREATE POLICY own_requests_read ON public.game_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.admin_is_unlocked());
CREATE OR REPLACE FUNCTION public.validate_request_insert_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN NEW.status='open'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_insert_status BEFORE INSERT ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_insert_status();
CREATE OR REPLACE FUNCTION public.validate_request_unique() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE key text; BEGIN key=regexp_replace(lower(trim(NEW.title)),'[^[:alnum:]]','','g'); PERFORM pg_advisory_xact_lock(hashtext('request:'||key)); IF EXISTS(SELECT 1 FROM game_requests WHERE id<>NEW.id AND regexp_replace(lower(trim(title)),'[^[:alnum:]]','','g')=key AND status IN ('open','review','resolved')) THEN RAISE EXCEPTION 'Já existe um pedido desse jogo. Vote no pedido existente.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_unique BEFORE INSERT OR UPDATE OF title ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_unique();
CREATE OR REPLACE FUNCTION public.admin_set_request_status(_request uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF _status NOT IN ('open','review','resolved','rejected') THEN RAISE EXCEPTION 'Status inválido'; END IF; UPDATE game_requests SET status=_status WHERE id=_request; IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF; INSERT INTO admin_audit(actor_id,action,resource,details) VALUES(auth.uid(),'request_status',_request::text,jsonb_build_object('status',_status)); END $$;
REVOKE ALL ON FUNCTION public.admin_set_request_status(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_request_status(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_overview() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN jsonb_build_object('users',(SELECT count(*) FROM profiles),'ratings',(SELECT count(*) FROM game_ratings),'requests',(SELECT count(*) FROM game_requests),'opens',(SELECT count(*) FROM play_events),'request_list',coalesce((SELECT jsonb_agg(t) FROM (SELECT r.id,r.title,r.status,r.created_at,(SELECT count(*) FROM request_votes v WHERE v.request_id=r.id) votes FROM game_requests r ORDER BY r.created_at DESC LIMIT 100)t),'[]'::jsonb),'audit',coalesce((SELECT jsonb_agg(t) FROM (SELECT actor_id,action,resource,created_at FROM admin_audit ORDER BY created_at DESC LIMIT 100)t),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.admin_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_overview() TO authenticated;
CREATE TABLE public.game_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,game_name text NOT NULL,message text NOT NULL CHECK(char_length(message) BETWEEN 5 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),hidden boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_comments TO authenticated;
GRANT ALL ON public.game_comments TO service_role;
ALTER TABLE public.game_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_own_read ON public.game_comments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY comments_own_insert ON public.game_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT hidden);
CREATE POLICY comments_own_update ON public.game_comments FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY comments_own_delete ON public.game_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.comment_likes(comment_id uuid NOT NULL REFERENCES public.game_comments(id) ON DELETE CASCADE,user_id uuid NOT NULL,PRIMARY KEY(comment_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.comment_likes TO authenticated;
GRANT ALL ON public.comment_likes TO service_role;
ALTER TABLE public.comment_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_own_read ON public.comment_likes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY likes_own_delete ON public.comment_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.can_like_comment(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM game_comments WHERE id=_id AND NOT hidden AND user_id<>auth.uid()) $$;
REVOKE ALL ON FUNCTION public.can_like_comment(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_like_comment(uuid) TO authenticated;
CREATE POLICY likes_own_insert ON public.comment_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.can_like_comment(comment_id));
CREATE TABLE public.xp_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,event_key text NOT NULL,points integer NOT NULL CHECK(points BETWEEN 1 AND 100),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
GRANT SELECT ON public.xp_events TO authenticated;
GRANT ALL ON public.xp_events TO service_role;
ALTER TABLE public.xp_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY xp_own ON public.xp_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.award_social_xp() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; p integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.user_id::text)); IF TG_TABLE_NAME='game_ratings' THEN k='rating:'||NEW.game_name; p=5; ELSIF TG_TABLE_NAME='request_votes' THEN k='vote:'||NEW.request_id::text;p=2; ELSE RETURN NEW; END IF; IF (SELECT coalesce(sum(points),0) FROM xp_events WHERE user_id=NEW.user_id AND created_at::date=current_date)+p<=50 THEN INSERT INTO xp_events(user_id,event_key,points) VALUES(NEW.user_id,k,p) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER rating_xp AFTER INSERT ON public.game_ratings FOR EACH ROW EXECUTE FUNCTION public.award_social_xp();
CREATE TRIGGER vote_xp AFTER INSERT ON public.request_votes FOR EACH ROW EXECUTE FUNCTION public.award_social_xp();
CREATE OR REPLACE FUNCTION public.validate_comment_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM consume_action_budget('comment',10,3600); IF TG_OP='INSERT' THEN NEW.created_at=now();NEW.hidden=false; ELSE NEW.created_at=OLD.created_at;NEW.user_id=OLD.user_id;NEW.game_name=OLD.game_name; IF NEW.hidden<>OLD.hidden AND NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER comment_write BEFORE INSERT OR UPDATE ON public.game_comments FOR EACH ROW EXECUTE FUNCTION public.validate_comment_write();
CREATE TRIGGER like_budget BEFORE INSERT OR DELETE ON public.comment_likes FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE OR REPLACE FUNCTION public.comment_page(_game text,_sort text DEFAULT 'recent',_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT c.id,c.message,c.created_at,c.updated_at,p.display_name,(c.user_id=auth.uid()) AS is_mine,(SELECT count(*) FROM comment_likes l WHERE l.comment_id=c.id) likes,EXISTS(SELECT 1 FROM comment_likes l WHERE l.comment_id=c.id AND l.user_id=auth.uid()) liked FROM game_comments c JOIN profiles p ON p.id=c.user_id WHERE c.game_name=_game AND NOT c.hidden ORDER BY CASE WHEN _sort='likes' THEN (SELECT count(*) FROM comment_likes l WHERE l.comment_id=c.id) ELSE 0 END DESC,c.created_at DESC,c.id LIMIT 20 OFFSET greatest(0,least(_offset,10000)))t $$;
REVOKE ALL ON FUNCTION public.comment_page(text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.comment_page(text,text,integer) TO anon,authenticated;
CREATE INDEX comments_game_date ON public.game_comments(game_name,created_at DESC);
CREATE INDEX xp_user_date ON public.xp_events(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.player_progress() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('xp',coalesce((SELECT sum(points) FROM xp_events WHERE user_id=auth.uid()),0),'ratings',(SELECT count(*) FROM game_ratings WHERE user_id=auth.uid()),'comments',(SELECT count(*) FROM game_comments WHERE user_id=auth.uid()),'games',(SELECT count(*) FROM player_library WHERE user_id=auth.uid() AND played_at IS NOT NULL),'activity',coalesce((SELECT jsonb_agg(t) FROM (SELECT event_key,points,created_at FROM xp_events WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 30)t),'[]'::jsonb)) $$;
REVOKE ALL ON FUNCTION public.player_progress() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.player_progress() TO authenticated;
CREATE OR REPLACE FUNCTION public.community_summary() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('plays',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,count(DISTINCT user_id) AS plays FROM play_events GROUP BY game_name ORDER BY count(DISTINCT user_id) DESC,game_name LIMIT 20)t),'[]'::jsonb),'ratings',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,avg(rating) AS average,count(*) AS votes FROM game_ratings GROUP BY game_name ORDER BY (sum(rating)+15.0)/(count(*)+5) DESC,game_name LIMIT 100)t),'[]'::jsonb),'players',coalesce((SELECT jsonb_agg(t) FROM (SELECT md5(p.id::text) AS id,p.display_name,p.avatar_url,coalesce((SELECT sum(points) FROM xp_events x WHERE x.user_id=p.id),0) AS plays FROM profiles p WHERE p.leaderboard_enabled ORDER BY plays DESC,p.display_name,p.id LIMIT 20)t),'[]'::jsonb),'requests',coalesce((SELECT jsonb_agg(t) FROM (SELECT r.id,CASE WHEN r.user_id=auth.uid() THEN r.user_id ELSE NULL END user_id,r.title,r.description,r.status,r.created_at,p.display_name,(SELECT count(*) FROM request_votes v WHERE v.request_id=r.id) AS votes FROM game_requests r JOIN profiles p ON p.id=r.user_id ORDER BY votes DESC,r.created_at DESC,r.id LIMIT 100)t),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.community_summary() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.community_summary() TO anon,authenticated;
CREATE TABLE public.save_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,game_name text NOT NULL,slot text NOT NULL DEFAULT 'Principal',object_name text NOT NULL UNIQUE,checksum text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 0 AND 10485760),version integer NOT NULL CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,game_name,slot,version));
GRANT SELECT ON public.save_versions TO authenticated;
GRANT ALL ON public.save_versions TO service_role;
ALTER TABLE public.save_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_save_versions ON public.save_versions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX save_versions_user_game ON public.save_versions(user_id,game_name,slot,version DESC);
CREATE OR REPLACE FUNCTION public.register_save_version(_game text,_slot text,_object text,_checksum text,_base integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE latest integer; bytes bigint; v uuid; BEGIN IF auth.uid() IS NULL OR split_part(_object,'/',1)<>auth.uid()::text OR _checksum !~ '^[a-f0-9]{64}$' OR length(_slot) NOT BETWEEN 1 AND 50 OR length(_game) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Save inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text||_game||_slot)); SELECT coalesce(max(version),0) INTO latest FROM save_versions WHERE user_id=auth.uid() AND game_name=_game AND slot=_slot; IF latest<>_base THEN RETURN jsonb_build_object('conflict',true,'latest',latest); END IF; SELECT (metadata->>'size')::bigint INTO bytes FROM storage.objects WHERE bucket_id='player-saves' AND name=_object; IF bytes IS NULL OR bytes>10485760 THEN RAISE EXCEPTION 'Arquivo não encontrado ou grande demais'; END IF; IF (SELECT coalesce(sum(size_bytes),0) FROM save_versions WHERE user_id=auth.uid())+bytes>104857600 THEN RAISE EXCEPTION 'Quota de 100 MB atingida'; END IF; PERFORM consume_action_budget('save',20,3600); INSERT INTO save_versions(user_id,game_name,slot,object_name,checksum,size_bytes,version) VALUES(auth.uid(),_game,_slot,_object,_checksum,bytes,latest+1) RETURNING id INTO v; RETURN jsonb_build_object('conflict',false,'version',latest+1,'id',v); END $$;
REVOKE ALL ON FUNCTION public.register_save_version(text,text,text,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.register_save_version(text,text,text,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_object_can_delete(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM save_versions WHERE object_name=_name) $$;
REVOKE ALL ON FUNCTION public.save_object_can_delete(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_object_can_delete(text) TO authenticated;
CREATE POLICY saves_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text AND public.save_object_can_delete(name));
CREATE OR REPLACE FUNCTION public.save_upload_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (SELECT coalesce(sum((metadata->>'size')::bigint),0) FROM storage.objects WHERE bucket_id='player-saves' AND split_part(name,'/',1)=auth.uid()::text)<=94371840 AND (SELECT count(*) FROM storage.objects WHERE bucket_id='player-saves' AND split_part(name,'/',1)=auth.uid()::text)<100 $$;
REVOKE ALL ON FUNCTION public.save_upload_allowed() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_upload_allowed() TO authenticated;
CREATE POLICY saves_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text AND name ~* '\.(sav|srm|state|json|zip|dat)$' AND public.save_upload_allowed());
CREATE TABLE public.content_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,comment_id uuid NOT NULL REFERENCES public.game_comments(id) ON DELETE CASCADE,reason text NOT NULL CHECK(char_length(reason) BETWEEN 5 AND 500),created_at timestamptz NOT NULL DEFAULT now(),resolved boolean NOT NULL DEFAULT false,UNIQUE(user_id,comment_id));
GRANT SELECT,INSERT ON public.content_reports TO authenticated;
GRANT ALL ON public.content_reports TO service_role;
ALTER TABLE public.content_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_report_insert ON public.content_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT resolved);
CREATE POLICY own_report_read ON public.content_reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR admin_is_unlocked());
CREATE TRIGGER report_budget BEFORE INSERT ON public.content_reports FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE OR REPLACE FUNCTION public.force_report_created_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.created_at = now(); RETURN NEW; END $$;
CREATE TRIGGER report_created_at BEFORE INSERT ON public.content_reports FOR EACH ROW EXECUTE FUNCTION public.force_report_created_at();
CREATE OR REPLACE FUNCTION public.admin_moderate_comment(_id uuid,_hidden boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; PERFORM consume_action_budget('admin_moderation',60,60); UPDATE game_comments SET hidden=_hidden WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Comentário não encontrado'; END IF; INSERT INTO admin_audit(actor_id,action,resource,details) VALUES(auth.uid(),'comment_moderation',_id::text,jsonb_build_object('hidden',_hidden)); UPDATE content_reports SET resolved=true WHERE comment_id=_id; END $$;
REVOKE ALL ON FUNCTION public.admin_moderate_comment(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_moderate_comment(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_reports() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN coalesce((SELECT jsonb_agg(t) FROM (SELECT r.id,r.comment_id,r.reason,r.created_at,c.message,c.game_name,c.hidden FROM content_reports r JOIN game_comments c ON c.id=r.comment_id WHERE NOT r.resolved ORDER BY r.created_at LIMIT 100)t),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.admin_reports() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_reports() TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_lock() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF; UPDATE admin_access SET expires_at=now() WHERE user_id=auth.uid(); IF FOUND THEN INSERT INTO admin_audit(actor_id,action) VALUES(auth.uid(),'admin_lock'); END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_lock() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_lock() TO authenticated;
CREATE TABLE public.catalog_registry(game_name text PRIMARY KEY,source_url text NOT NULL,category text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),display_name text,enabled boolean NOT NULL DEFAULT true,overridden boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.catalog_registry TO anon,authenticated;
GRANT ALL ON public.catalog_registry TO service_role;
ALTER TABLE public.catalog_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_public ON public.catalog_registry FOR SELECT TO anon,authenticated USING(true);
CREATE OR REPLACE FUNCTION public.validate_catalog_action() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM catalog_registry WHERE game_name=NEW.game_name) THEN RAISE EXCEPTION 'Jogo não encontrado no catálogo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_rating_game BEFORE INSERT OR UPDATE ON public.game_ratings FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_action();
CREATE TRIGGER validate_play_game BEFORE INSERT ON public.play_events FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_action();
CREATE TRIGGER validate_comment_game BEFORE INSERT OR UPDATE ON public.game_comments FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_action();
CREATE TRIGGER validate_library_game BEFORE INSERT OR UPDATE ON public.player_library FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_action();
CREATE TRIGGER validate_save_game BEFORE INSERT ON public.save_versions FOR EACH ROW EXECUTE FUNCTION public.validate_catalog_action();
CREATE TABLE public.catalog_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_name text NOT NULL,actor_id uuid NOT NULL,before_data jsonb,after_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.catalog_revisions TO authenticated;
GRANT ALL ON public.catalog_revisions TO service_role;
ALTER TABLE public.catalog_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_catalog_revisions ON public.catalog_revisions FOR SELECT TO authenticated USING(admin_is_unlocked());
CREATE OR REPLACE FUNCTION public.admin_catalog_edit(_game text,_display text,_url text,_category text,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prior catalog_registry; BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF length(_game) NOT BETWEEN 1 AND 200 OR length(_display) NOT BETWEEN 1 AND 200 OR _url !~ '^https://[^/@[:space:]]+([/?#]|$)' OR length(_url)>2000 OR length(_category)>50 THEN RAISE EXCEPTION 'Dados do jogo inválidos'; END IF; PERFORM consume_action_budget('admin_catalog',30,60); SELECT * INTO prior FROM catalog_registry WHERE game_name=_game FOR UPDATE; INSERT INTO catalog_registry(game_name,display_name,source_url,category,enabled,overridden) VALUES(_game,_display,_url,_category,_enabled,true) ON CONFLICT(game_name) DO UPDATE SET display_name=excluded.display_name,source_url=excluded.source_url,category=excluded.category,enabled=excluded.enabled,overridden=true,updated_at=now(); INSERT INTO catalog_revisions(game_name,actor_id,before_data,after_data) VALUES(_game,auth.uid(),to_jsonb(prior),jsonb_build_object('display_name',_display,'source_url',_url,'category',_category,'enabled',_enabled)); INSERT INTO admin_audit(actor_id,action,resource) VALUES(auth.uid(),'catalog_edit',_game); END $$;
REVOKE ALL ON FUNCTION public.admin_catalog_edit(text,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_catalog_edit(text,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_user_list(_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN coalesce((SELECT jsonb_agg(t) FROM (SELECT p.id,p.display_name,p.leaderboard_enabled,coalesce((SELECT sum(points) FROM xp_events x WHERE x.user_id=p.id),0) xp,coalesce((SELECT jsonb_agg(role) FROM user_roles r WHERE r.user_id=p.id),'[]'::jsonb) roles FROM profiles p ORDER BY p.display_name,p.id LIMIT 30 OFFSET greatest(0,_offset))t),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.admin_user_list(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_user_list(integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_moderator(_user uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; PERFORM consume_action_budget('admin_roles',20,60); IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_user) THEN RAISE EXCEPTION 'Conta não encontrada'; END IF; IF _enabled THEN INSERT INTO user_roles(user_id,role) VALUES(_user,'moderator') ON CONFLICT DO NOTHING; ELSE DELETE FROM user_roles WHERE user_id=_user AND role='moderator'; END IF; INSERT INTO admin_audit(actor_id,action,resource,details) VALUES(auth.uid(),'moderator_role',_user::text,jsonb_build_object('enabled',_enabled)); END $$;
REVOKE ALL ON FUNCTION public.admin_set_moderator(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_moderator(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_remove_rating(_user uuid,_game text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; DELETE FROM game_ratings WHERE user_id=_user AND game_name=_game; INSERT INTO admin_audit(actor_id,action,resource) VALUES(auth.uid(),'rating_remove',_user::text||':'||_game); END $$;
REVOKE ALL ON FUNCTION public.admin_remove_rating(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_remove_rating(uuid,text) TO authenticated;
CREATE TABLE public.rtc_closed_rooms(room_id uuid PRIMARY KEY,closed_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rtc_closed_rooms TO service_role;
ALTER TABLE public.rtc_closed_rooms ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.rtc_close_room(_room uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room AND host_id=auth.uid()) THEN RAISE EXCEPTION 'Somente o anfitrião pode encerrar'; END IF; INSERT INTO rtc_closed_rooms(room_id) VALUES(_room) ON CONFLICT DO NOTHING; DELETE FROM rtc_rooms WHERE id=_room AND host_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.rtc_close_room(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rtc_close_room(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.rtc_guarded_exchange(_room uuid,_peer uuid,_op text DEFAULT 'poll',_name text DEFAULT '',_since bigint DEFAULT 0,_to uuid DEFAULT NULL,_kind text DEFAULT NULL,_payload jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF; PERFORM pg_advisory_xact_lock(hashtext(_room::text)); IF EXISTS(SELECT 1 FROM rtc_closed_rooms WHERE room_id=_room) THEN RAISE EXCEPTION 'Convite encerrado'; END IF; IF EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room AND expires_at<=now()) THEN INSERT INTO rtc_closed_rooms(room_id) VALUES(_room) ON CONFLICT DO NOTHING; RETURN jsonb_build_object('closed',true,'peers','[]'::jsonb,'signals','[]'::jsonb); END IF; IF _op='poll' THEN PERFORM consume_action_budget('rtc_poll',300,60); IF NOT EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room) THEN PERFORM consume_action_budget('rtc_create',5,3600); END IF; ELSIF _op='signal' THEN PERFORM consume_action_budget('rtc_signal',120,60); END IF; RETURN rtc_exchange(_room,_peer,_op,_name,_since,_to,_kind,_payload); END $$;
REVOKE ALL ON FUNCTION public.rtc_guarded_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rtc_guarded_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.rtc_retire_expired() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO rtc_closed_rooms(room_id) VALUES(OLD.id) ON CONFLICT DO NOTHING; RETURN OLD; END $$;
CREATE TRIGGER rtc_retire_room BEFORE DELETE ON public.rtc_rooms FOR EACH ROW EXECUTE FUNCTION public.rtc_retire_expired();
CREATE OR REPLACE FUNCTION public.clamp_library_played_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  IF NEW.played_at IS NOT NULL AND NEW.played_at > now() THEN NEW.played_at = now(); END IF;
  IF TG_OP = 'UPDATE' AND OLD.played_at IS NOT NULL AND (NEW.played_at IS NULL OR NEW.played_at < OLD.played_at) THEN NEW.played_at = OLD.played_at; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER library_played_at BEFORE INSERT OR UPDATE ON public.player_library FOR EACH ROW EXECUTE FUNCTION public.clamp_library_played_at();